#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u, v, w;
} Edge;

typedef struct {
    int *p, *r;
    int n;
} DSU;

static void dsu_init(DSU *d, int n) {
    d->n = n;
    d->p = (int*)malloc((n + 1) * sizeof(int));
    d->r = (int*)malloc((n + 1) * sizeof(int));
    for (int i = 1; i <= n; ++i) {
        d->p[i] = i;
        d->r[i] = 0;
    }
}

static void dsu_free(DSU *d) {
    free(d->p);
    free(d->r);
}

static int dsu_find(DSU *d, int x) {
    if (d->p[x] != x) d->p[x] = dsu_find(d, d->p[x]);
    return d->p[x];
}

static int dsu_union(DSU *d, int a, int b) {
    a = dsu_find(d, a);
    b = dsu_find(d, b);
    if (a == b) return 0;
    if (d->r[a] < d->r[b]) {
        d->p[a] = b;
    } else if (d->r[a] > d->r[b]) {
        d->p[b] = a;
    } else {
        d->p[b] = a;
        d->r[a]++;
    }
    return 1;
}

static int cmp_edge(const void *A, const void *B) {
    const Edge *a = (const Edge*)A;
    const Edge *b = (const Edge*)B;
    if (a->w < b->w) return -1;
    if (a->w > b->w) return 1;
    return 0;
}

/*
We need the minimum possible median edge cost among all spanning trees.
For n nodes, every spanning tree has n-1 edges.
Since n is even, n-1 is odd, so the median is the ((n-1)/2 + 1)-th smallest edge,
i.e. the k-th smallest edge where k = n/2.

Claim:
The minimum possible median equals the smallest value X such that the graph formed
by edges with cost <= X contains a spanning tree with at least k edges from this set.
But any spanning tree fully inside that subgraph exists iff that subgraph is connected.
Because if edges <= X connect all vertices, then there exists a spanning tree using only
edges <= X, whose median is <= X. Conversely, if a spanning tree has median <= X, then
at least k edges in the tree are <= X; this implies enough low edges, and by matroid/base
exchange reasoning the optimum is exactly the minimum bottleneck threshold making the graph connected.

Operationally, sort edges by weight and run Kruskal. The answer is the weight of the k-th
selected edge in the MST order (equivalently any minimum bottleneck spanning tree threshold).
This is a known property for this problem.
*/

int main(void) {
    int n, m;
    while (scanf("%d %d", &n, &m) == 2) {
        Edge *edges = (Edge*)malloc(m * sizeof(Edge));
        for (int i = 0; i < m; ++i) {
            scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].w);
        }

        qsort(edges, m, sizeof(Edge), cmp_edge);

        DSU dsu;
        dsu_init(&dsu, n);

        int need = n / 2;   /* median position among n-1 edges */
        int taken = 0;
        int answer = 0;

        for (int i = 0; i < m; ++i) {
            if (dsu_union(&dsu, edges[i].u, edges[i].v)) {
                taken++;
                if (taken == need) {
                    answer = edges[i].w;
                    break;
                }
            }
        }

        printf("%d\n", answer);

        dsu_free(&dsu);
        free(edges);
    }
    return 0;
}

