            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        boolean union(int x, int y) {
            int rx = find(x), ry = find(y);
            if (rx == ry) return false;
            if (rank[rx] < rank[ry]) parent[rx] = ry;
            else if (rank[rx] > rank[ry]) parent[ry] = rx;
            else { parent[ry] = rx; rank[rx]++; }
            return true;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            int n = sc.nextInt(), m = sc.nextInt();
            if (n == 0 && m == 0) break;
            Edge[] edges = new Edge[m];
            int[] costs = new int[m];
            for (int i = 0; i < m; i++) {
                int u = sc.nextInt(), v = sc.nextInt(), c = sc.nextInt();
                edges[i] = new Edge(u, v, c);
                costs[i] = c;
            }
            Arrays.sort(costs);
            int lo = 0, hi = m - 1, ans = costs[hi];
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                int limit = costs[mid];
                if (canBuild(n, edges, limit)) {
                    ans = limit;
                    hi = mid - 1;
                } else {
                    lo = mid + 1;
                }
            }
            System.out.println(ans);
        }
        sc.close();
    }

    static boolean canBuild(int n, Edge[] edges, int limit) {
        DSU dsu = new DSU(n);
        // Count edges <= limit as weight 0, > limit as weight 1
        // Sort by weight then cost to prefer cheaper edges for tie-breaking
        List<Edge> list = new ArrayList<>();
        for (Edge e : edges) {
            list.add(e);
        }
        list.sort((a, b) -> {
            int wa = a.cost <= limit ? 0 : 1;
            int wb = b.cost <= limit ? 0 : 1;
            if (wa != wb) return wa - wb;
            return a.cost - b.cost;
        });
        int totalWeight = 0;
        int taken = 0;
        for (Edge e : list) {
            if (dsu.union(e.u, e.v)) {
                if (e.cost > limit) totalWeight++;
                taken++;
                if (taken == n - 1) break;
            }
        }
        // We need at least n/2 edges with cost <= limit
        // That means at most (n-1 - n/2) = n/2 - 1 edges > limit
        return totalWeight <= n/2 - 1;
    }
}

