/*
We need the minimum possible median edge cost among all spanning trees
of a connected undirected graph with an even number of vertices.

Let N be even. A spanning tree has N-1 edges, so its median is the
(N/2)-th smallest edge in the tree (1-indexed).

Claim:
A value X is feasible as the median of some spanning tree iff the graph
formed by edges with cost <= X has at least N/2 + 1 vertices in one
connected component, equivalently its number of connected components is
<= N/2.

Reason:
To have median <= X, a spanning tree must contain at least N/2 edges
with cost <= X. Any forest on N vertices with c connected components has
at most N-c edges. Thus we need N-c >= N/2 => c <= N/2.
Conversely, if c <= N/2, take a spanning forest of the <=X edges
(using N-c such edges), then connect the components with arbitrary edges.
This yields a spanning tree with at least N-c >= N/2 edges of cost <= X,
so the median is <= X.

Therefore answer = minimum X such that the subgraph of edges with cost <= X
has at most N/2 connected components.

We can binary search over sorted unique edge costs and use DSU to count
components for each check.

Input format:
Multiple datasets, each starts with n m.
Assume terminated by "0 0".
For each dataset, m lines: u v w

Output one answer per dataset.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Integer.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int u, v, w;
        Edge(int u, int v, int w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
    }

    static class DSU {
        int[] p, r;
        int comps;

        DSU(int n) {
            p = new int[n + 1];
            r = new int[n + 1];
            comps = n;
            for (int i = 1; i <= n; i++) p[i] = i;
        }

        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }

        boolean union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return false;
            if (r[ra] < r[rb]) {
                p[ra] = rb;
            } else if (r[ra] > r[rb]) {
                p[rb] = ra;
            } else {
                p[rb] = ra;
                r[ra]++;
            }
            comps--;
            return true;
        }
    }

    static boolean feasible(int n, Edge[] edges, int x) {
        DSU dsu = new DSU(n);
        for (Edge e : edges) {
            if (e.w <= x) dsu.union(e.u, e.v);
        }
        return dsu.comps <= n / 2;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n = fs.nextInt();
            if (n == Integer.MIN_VALUE) break;
            int m = fs.nextInt();

            if (n == 0 && m == 0) break;

            Edge[] edges = new Edge[m];
            int[] costs = new int[m];
            for (int i = 0; i < m; i++) {
                int u = fs.nextInt();
                int v = fs.nextInt();
                int w = fs.nextInt();
                edges[i] = new Edge(u, v, w);
                costs[i] = w;
            }

            Arrays.sort(costs);
            int k = 0;
            for (int i = 0; i < m; i++) {
                if (i == 0 || costs[i] != costs[i - 1]) {
                    costs[k++] = costs[i];
                }
            }

            int lo = 0, hi = k - 1, ans = costs[k - 1];
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                int x = costs[mid];
                if (feasible(n, edges, x)) {
                    ans = x;
                    hi = mid - 1;
                } else {
                    lo = mid + 1;
                }
            }

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}

