class DSU:
    __slots__ = ("p", "r")
    def __init__(self, n):
        self.p = list(range(n))
        self.r = [0] * n

    def find(self, x):
        p = self.p
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x

    def union(self, a, b):
        a = self.find(a)
        b = self.find(b)
        if a == b:
            return False
        if self.r[a] < self.r[b]:
            a, b = b, a
        self.p[b] = a
        if self.r[a] == self.r[b]:
            self.r[a] += 1
        return True


def can_make(edges, n, x, need):
    """
    Check whether there exists a spanning tree containing at least `need`
    edges with cost <= x.

    This is equivalent to asking whether the graph formed only by edges
    with cost <= x has at most n - need connected components, because a
    spanning tree can include at most (n - c) such edges where c is the
    number of components in that subgraph.
    """
    dsu = DSU(n)
    for u, v, w in edges:
        if w <= x:
            dsu.union(u, v)

    comps = 0
    for i in range(n):
        if dsu.find(i) == i:
            comps += 1

    return (n - comps) >= need


