    it = iter(data)
    out = []

    while True:
        try:
            n = int(next(it))
            m = int(next(it))
        except StopIteration:
            break

        if n == 0 and m == 0:
            break

        edges = []
        costs = []
        for _ in range(m):
            u = int(next(it))
            v = int(next(it))
            w = int(next(it))
            u -= 1
            v -= 1
            edges.append((u, v, w))
            costs.append(w)

        costs = sorted(set(costs))

        # For even n, spanning tree has n-1 edges, and its median is the
        # (n/2)-th smallest edge in 1-based indexing, i.e. we need at least
        # n/2 edges <= answer.
        need = n // 2

        lo, hi = 0, len(costs) - 1
        ans = costs[-1]
        while lo <= hi:
            mid = (lo + hi) // 2
            x = costs[mid]
            if can_make(edges, n, x, need):
                ans = x
                hi = mid - 1
            else:
                lo = mid + 1

        out.append(str(ans))

    return "\n".join(out)


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    print(solve(data))

if __name__ == "__main__":
    main()
